package net.civeira.phylax.features.access.tenantconfig.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class WelcomeEmailVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property welcome email of tenant config ")
  void test_welcome_email_v_o_builder() {
    Assertions.assertFalse(WelcomeEmailVO.nullValue().getWelcomeEmail().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(WelcomeEmailVO.tryFrom(null).getWelcomeEmail().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", WelcomeEmailVO.from("one").getWelcomeEmail().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> WelcomeEmailVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", WelcomeEmailVO.from("one").toString());
  }
}
